```
const {ul, li} = drag;
const dy = clientY - drag.startY;
const movingCenter = drag.center0 + dy;  // center0 measured at drag start (offsetTop-based)
// target index among siblings
const sibs = [...ul.children].filter(x=>x!==li);
let target = 0;
for(const sib of sibs){
  if(movingCenter < sib.offsetTop + sib.offsetHeight/2) break;
  target++;
}
// current index
const all = [...ul.children];
const cur = all.indexOf(li);
if(target !== cur){
  const beforeTop = li.offsetTop;
  // FLIP for other items
  flipReorder(ul, li, sibs[target] ?? null);
  const afterTop = li.offsetTop;
  drag.topShift += beforeTop - afterTop;
}
li.style.transform = `translateY(${dy + drag.topShift}px)`;
```

flipReorder with FLIP animation on the other items:
```
function flipReorder(ul, item, ref){
  const els = [...ul.children];
  const first = new Map(els.map(el=>[el, el.offsetTop]));
  ul.insertBefore(item, ref);
  const moved = ul.children.length === els.length; // always true
  [...ul.children].forEach(el=>{
    if(el===item) return;
    const delta = (first.get(el) ?? el.offsetTop) - el.offsetTop;
    if(Math.abs(delta)>2){
      el.style.transition='none';
      el.style.transform=`translateY(${delta}px)`;
      // force reflow, then animate to 0
      void el.offsetWidth;
      el.style.transition='transform 150ms ease';
      el.style.transform='';
      const clean=()=>{ el.style.transition=''; el.removeEventListener('transitionend',clean); };
      el.addEventListener('transitionend', clean, {once:true});
    }
  });
}
```

