```js
function collect(){
  const payload=[];
  document.querySelectorAll('.list').forEach((ul, li)=>{
    [...ul.children].forEach((el, pos)=> payload.push({pos, type: el.dataset.type}));
  });
  const count=(arr,ch)=>arr.reduce((a,v)=>a+(v===ch?1:0),0);
  const maj = payload.filter(x=>x.pos===0).map(x=>x.type);
  const min = payload.filter(x=>x.pos===3).map(x=>x.type);
  return {
    d: count(maj,'d')-count(min,'d'),
    i: count(maj,'i')-count(min,'i'),
    s: count(maj,'s')-count(min,'s'),
    c: count(maj,'c')-count(min,'c'),
  };
}
```

