  if (document.getElementById('discModal').hidden) fail('modal not open'); else ok('modal open');

  // 3. simulated drag on first list: drag item0 down under item1
  const ul0 = lists[0];
  const a = ul0.children[0], b = ul0.children[1];
  const h = a.offsetHeight || 47;
  const r = a.getBoundingClientRect();
  const x = r.left + 30, y = r.top + r.height / 2;
  const pd = new PointerEvent('pointerdown', {pointerId: 7, pointerType: 'mouse', button: 0, clientX: x, clientY: y, bubbles: true});
  a.dispatchEvent(pd);
  for (let dy = 8; dy <= h + 6; dy += (h + 6) / 8) {
    a.dispatchEvent(new PointerEvent('pointermove', {pointerId: 7, pointerType: 'mouse', clientX: x, clientY: y + dy, bubbles: true}));
  }
  a.dispatchEvent(new PointerEvent('pointerup', {pointerId: 7, pointerType: 'mouse', clientX: x, clientY: y + h + 6, bubbles: true}));
  if (ul0.children[0] === b && ul0.children[1] === a) ok('drag swapped item0<->item1');
  else fail('drag did not swap: order=' + [...ul0.children].map(li=>li.dataset.type).join(','));
  const ranks = [...ul0.children].map(li => li.querySelector('.rank').textContent);
  if (ranks.join('') !== '1234') fail('ranks not updated: ' + ranks.join(',')); else ok('ranks 1-4 after drag');

  // 4. set all lists to deterministic order: d first, c last (i,s in middle)
  const want = ['d','i','s','c'];
  for (const ul of lists) {
    const byType = {};
    [...ul.children].forEach(li => byType[li.dataset.type] = li);
    want.forEach(t => ul.appendChild(byType[t]));
  }
  // 5. walk steps: click Далее 7 times, then finish
  const next = document.getElementById('btnNext');
  for (let i = 0; i < 6; i++) next.click();
  if (!document.getElementById('btnNext').hidden === false) ok('next hidden on last step');
  if (!document.getElementById('btnFinish').hidden) fail('finish not visible on last step');
  document.getElementById('btnFinish').click();

  const scores = document.getElementById('resultScores').textContent;
  if (scores === 'D:24, I:0, S:0, C:-24') ok('score line exact: ' + scores); else fail('score line: ' + scores);
  const rows = document.querySelectorAll('#profileBars .profile__row');
  if (rows.length !== 4) fail('profile rows != 4'); else ok('4 profile rows');
  if (document.getElementById('tabs').hidden) ok('tabs hidden in result');
  if (!document.querySelector('.result.is-active')) fail('result not active');

  // 6. restart works
  document.getElementById('btnRestart').click();
  const ul1 = lists[0];
  if (ul1.children[0] !== a) fail('restart did not restore order: ' + [...ul1.children].map(li=>li.dataset.type).join(','));
  else ok('restart restores original order');
  if (!document.getElementById('tabs').hidden) ok('tabs back after restart');
  if (!document.getElementById('discModal').hidden) { /* still open */ }
  document.querySelector('.result.is-active').classList.remove('is-active');
  if (document.querySelectorAll('#panes .pane.is-active').length === 1) ok('pane0 active after restart');

  document.title = 'TESTDONE ' + out.join(' | ');
})();
</script>
'''
